static unsigned int find_insn(const insn_map_x86 *insns, unsigned int max, unsigned int id)
{
        // binary searching since the IDs are sorted in order
        unsigned int left, right, m;

        left = 0;
        right = max - 1;

        while(left <= right) {
                m = (left + right) / 2;
                if (id == insns[m].id) {
                        return m;
                }

                if (id < insns[m].id)
                        right = m - 1;
                else
                        left = m + 1;
        }

        // not found
        // printf("NOT FOUNDDDDDDDDDDDDDDD id = %u\n", id);
        return -1;
}

